import { existsSync, readFileSync } from "node:fs";
import { writeFile } from "node:fs/promises";

function readIfPresent(url) {
  return existsSync(url) ? readFileSync(url, "utf8") : null;
}

async function integrationPreviousRunCodeStep() {
  const workspaceRoot = new URL("../../", import.meta.url);
  await writeFile(
    new URL("generated.txt", workspaceRoot),
    "generated by the steered rerun\n",
  );
  return {
    summary: "read previous run",
    findings: readIfPresent(
      new URL(".boboddy/previous-run/findings.json", workspaceRoot),
    ),
    transcript: readIfPresent(
      new URL(".boboddy/previous-run/transcript.txt", workspaceRoot),
    ),
  };
}

export const previousRunStep = {
  key: "integration-step",
  name: "Integration Step",
  version: 1,
  kind: "code",
  entrypoint: { fn: integrationPreviousRunCodeStep },
};
